pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 a1, uint256 a2) internal {
        a1 = bound(a1, 0, 1000000000000000000000000000000);
        a2 = bound(a2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a1 + a2);
        try c.addToBalance{value: a1}() {} catch { return; }
        uint256 bal1;
        try c.getBalance(address(this)) returns (uint256 __r) { bal1 = __r; } catch { return; }
        uint cval1 = address(c).balance;
        try c.addToBalance{value: a2}() {} catch { return; }
        uint256 bal2;
        try c.getBalance(address(this)) returns (uint256 __r) { bal2 = __r; } catch { return; }
        uint cval2 = address(c).balance;
        assertTrue(bal2 >= bal1 && cval2 >= cval1);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
